 // Node: "Разбивка по частям документа"
// Mode: Run Once for All Items
// Position: после "Денормализация таблиц" (главный поток), читает version/language
// из "Очистка и разметка" по имени узла.
//
// Recursive Character Text Splitter с приоритетом по заголовкам разделов (Урок 162):
// заголовки задают предпочтительные границы, но не обязательные — мелкие смежные
// секции склеиваются (в пределах одного родительского ##), крупные режутся каскадно
// (абзацы -> предложения). Overlap убран — конфликтовал с Chunk Size на стороне
// Insert Documents / Recursive Character Text Splitter.
//
// НЕ проставляет topic — это отдельный, единственный project-specific шаг после этого
// узла ("Определение темы (topic)"). Всё остальное здесь универсально под любой PDF.

const UPSTREAM_NODE_NAMES = {
  cleanupTagging: 'Очистка и разметка',
  formTrigger: 'Загрузка документа',
};

const TARGET_MIN_CHARS = 400;
const TARGET_MAX_CHARS = 700;

function slugify(str) {
  return str
    .toLowerCase()
    .replace(/\.[a-z0-9]+$/i, '')
    .replace(/[^\p{L}\p{N}]+/gu, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 80);
}

function extractRelatedSections(text, ownSectionNum) {
  const found = new Set();
  const re = /(?:п\.?|пункт[а-я]*|раздел[а-я]*|см\.?)\s*(\d+(?:\.\d+)*)/gi;
  let m;
  while ((m = re.exec(text)) !== null) {
    const num = m[1];
    if (num && num !== ownSectionNum) found.add(num);
  }
  return Array.from(found);
}

const fullText = $input.first().json.text;
const version = $(UPSTREAM_NODE_NAMES.cleanupTagging).item.json.version;
const language = $(UPSTREAM_NODE_NAMES.cleanupTagging).item.json.language;
const rawTitle = $(UPSTREAM_NODE_NAMES.formTrigger).item.json['File'].filename;
const documentId = slugify(rawTitle);
const createdAt = new Date().toISOString();

// --- Шаг 1: секции по заголовкам ---
const lines = fullText.split('\n');
const rawSections = [];
let currentSection = 'Введение (преамбула)';
let currentParent = 'Введение (преамбула)';
let buffer = [];

function flush() {
  const text = buffer.join('\n').trim();
  if (text.length > 0) rawSections.push({ section: currentSection, parentSection: currentParent, text });
  buffer = [];
}

for (const line of lines) {
  const h2 = line.match(/^##\s+(.*)/);
  const h3 = line.match(/^###\s+(.*)/);
  if (h2) {
    flush();
    currentSection = h2[1].trim();
    currentParent = currentSection;
    buffer.push(line);
    continue;
  }
  if (h3) {
    flush();
    currentSection = h3[1].trim();
    buffer.push(line);
    continue;
  }
  buffer.push(line);
}
flush();

// --- Шаг 2: склейка мелких смежных секций ---
const merged = [];
for (const s of rawSections) {
  const prev = merged[merged.length - 1];
  if (prev && prev.parentSection === s.parentSection && prev.text.length < TARGET_MIN_CHARS) {
    prev.text = prev.text + '\n\n' + s.text;
  } else {
    merged.push({ ...s });
  }
}

// --- Шаг 3: каскадный разрез крупных секций ---
function splitOversized(text) {
  if (text.length <= TARGET_MAX_CHARS) return [text];
  const paras = text.split('\n\n');
  const parts = [];
  let cur = '';
  for (const p of paras) {
    const candidate = cur ? cur + '\n\n' + p : p;
    if (candidate.length > TARGET_MAX_CHARS && cur) {
      parts.push(cur.trim());
      cur = p;
    } else {
      cur = candidate;
    }
  }
  if (cur.trim().length > 0) parts.push(cur.trim());

  return parts.flatMap((part) => {
    if (part.length <= TARGET_MAX_CHARS) return [part];
    const sentences = part.split(/(?<=[.!?])\s+/);
    const subParts = [];
    let curS = '';
    for (const s of sentences) {
      const candidate = curS ? curS + ' ' + s : s;
      if (candidate.length > TARGET_MAX_CHARS && curS) {
        subParts.push(curS.trim());
        curS = s;
      } else {
        curS = candidate;
      }
    }
    if (curS.trim().length > 0) subParts.push(curS.trim());
    return subParts;
  });
}

const finalChunks = [];
for (const s of merged) {
  const parts = splitOversized(s.text);
  for (const p of parts) finalChunks.push({ section: s.section, text: p });
}

// --- Шаг 4: сборка с метаданными (без overlap, без topic) ---
return finalChunks.map((c, i) => {
  const sectionNum = (c.section.match(/^(\d+(?:\.\d+)?)/) || [])[1] || null;
  return {
    json: {
      text: c.text,
      title: rawTitle,
      document_id: documentId,
      version,
      language,
      section: c.section,
      chunk_index: i,
      is_current: true,
      source_type: 'document',
      valid_until: null,
      related_sections: extractRelatedSections(c.text, sectionNum),
      created_at: createdAt,
    },
  };
});

// Node: "Определение темы (topic)"
// Mode: Run Once for All Items
// Position: между "Разбивка по частям документа" и "Вставка чанков (addDocuments)".
//
// ⚠️ ЕДИНСТВЕННЫЙ project-specific узел во всём пайплайне. При переносе на другой
// документ/проект правишь только TOPIC_MAP здесь — весь остальной пайплайн (очистка,
// разметка, классификация типа, денормализация таблиц, сплиттер, вставка) остаётся
// без изменений, потому что нигде больше не знает про конкретные номера разделов.
//
// Карта "номер раздела -> тема" — совпадает со слайдом брифа "Источник базы знаний":
// Пороги согласования договоров, Матрица полномочий на подписание,
// Требования к внешним консультантам, Претензионно-исковая работа.

const TOPIC_MAP = [
  { prefix: '4', topic: 'Пороги согласования договоров' },
  { prefix: '5.2', exact: true, topic: 'Матрица полномочий на подписание' },
  { prefix: '6', topic: 'Претензионно-исковая работа' },
  { prefix: '9', topic: 'Требования к внешним консультантам' },
];

function topicFor(sectionLabel) {
  const num = (sectionLabel.match(/^(\d+(?:\.\d+)?)/) || [])[1];
  if (!num) return null;
  for (const rule of TOPIC_MAP) {
    const matches = rule.exact ? num === rule.prefix : (num === rule.prefix || num.startsWith(rule.prefix + '.'));
    if (matches) return rule.topic;
  }
  return null;
}

return $input.all().map((item) => ({
  json: {
    ...item.json,
    topic: topicFor(item.json.section),
  },
}));

// Node: "Очистка и разметка"
// Position: между "Извлечение текста из PDF" и "Денормализация таблиц".
// Mode: Run Once for Each Item.

// --- Шаг 1: очистка колонтитулов/номеров страниц ---
const raw = $input.item.json.text;
const lines = raw.split('\n').map((l) => l.trim());
const counts = {};
for (const line of lines) {
  if (line.length < 8) continue;
  counts[line] = (counts[line] || 0) + 1;
}
const noisy = new Set(
  Object.entries(counts).filter(([, count]) => count >= 3).map(([line]) => line)
);
const cleaned = lines.filter((line) => {
  if (noisy.has(line)) return false;
  if (/^(Страница|Page)\s*\d+\s*$/i.test(line)) return false;
  if (/^\d{1,4}$/.test(line)) return false;
  return true;
});
let text = cleaned.join('\n').replace(/\n{3,}/g, '\n\n').trim();

// --- Шаг 2: version, language, вычистка оглавления, разметка заголовков ---
const versionMatch = text.match(/(?:Версия|Version)[:\s]+(\d+\.\d+)/i);
const version = versionMatch ? versionMatch[1] : 'unknown';

const cyrillicCount = (text.match(/[а-яё]/gi) || []).length;
const latinCount = (text.match(/[a-z]/gi) || []).length;
const language = cyrillicCount >= latinCount ? 'ru' : 'en';

const isTocLineSingle = (l) => /^\d{1,2}\.\s+\S.*\s\d{1,4}$/.test(l.trim());
const isTocNumberOnly = (l) => /^\d{1,2}\.\s*$/.test(l.trim());
const isTocTitleWithPage = (l) => /^\S.*\s\d{1,4}$/.test(l.trim());
{
  const lines0 = text.split('\n');
  const kept = [];
  let i = 0;
  while (i < lines0.length) {
    let j = i;
    let entryCount = 0;
    while (j < lines0.length) {
      const line = lines0[j];
      const trimmed = line.trim();
      if (trimmed === '') { j++; continue; }
      if (isTocLineSingle(line)) { entryCount++; j++; continue; }
      if (isTocNumberOnly(line) && j + 1 < lines0.length && isTocTitleWithPage(lines0[j + 1])) {
        entryCount++; j += 2; continue;
      }
      break;
    }
    if (entryCount >= 4) { i = j; continue; }
    kept.push(lines0[i]);
    i++;
  }
  text = kept.join('\n');
}

const HEADER_MAX_LEN = 65;
const topPattern = /^(\d{1,2})\.\s+(\S.*)$/;
const subPattern = /^(\d{1,2}\.\d{1,2})\s+(\S.*)$/;
const appendixTop = /^(Приложение\s+[А-ЯA-Z])\.\s+(\S.*)$/i;
const appendixSub = /^([А-ЯA-Z]\.\d{1,2})\s+(\S.*)$/;

function looksLikeHeaderShape(t) {
  if (t.length === 0 || t.length > HEADER_MAX_LEN) return false;
  if (/[.!?,;:]$/.test(t)) return false;
  return topPattern.test(t) || subPattern.test(t) || appendixTop.test(t) || appendixSub.test(t);
}

const MIN_GAP_LINES = 4;
let lastAcceptedIdx = -Infinity;
let lastAcceptedTop = 0;
const outLines = text.split('\n').map((line, idx) => {
  const t = line.trim();
  if (!looksLikeHeaderShape(t)) return line;
  const topMatch = topPattern.exec(t);
  const isTop = topMatch && !subPattern.test(t);
  if (isTop) {
    const num = parseInt(topMatch[1], 10);
    if (num <= lastAcceptedTop || (idx - lastAcceptedIdx) < MIN_GAP_LINES) return line;
    lastAcceptedTop = num;
    lastAcceptedIdx = idx;
    return '## ' + t;
  }
  const isSub = subPattern.test(t) || appendixSub.test(t);
  return (isSub ? '### ' : '## ') + t;
});

const finalText = outLines.join('\n').replace(/\n{3,}/g, '\n\n').trim();

return { json: { text: finalText, version, language } };
